function formatCurrency(e){return e.toLocaleString("vi-VN")+"đ"}function formatNumber(e){return e.toLocaleString("vi-VN")}function formatPrice(e){return new Intl.NumberFormat("vi-VN").format(e||0)+"đ"}function getCurrentDate(){return(new Date).toLocaleDateString("vi-VN",{weekday:"long",year:"numeric",month:"long",day:"numeric"})}function getCurrentTime(){return(new Date).toLocaleTimeString("vi-VN",{hour:"2-digit",minute:"2-digit"})}function generateId(e="ID"){return e+Date.now().toString(36).toUpperCase()}const storage={get(e){try{const t=localStorage.getItem(e);return t?JSON.parse(t):null}catch(e){return console.error("Error reading from localStorage:",e),null}},set(e,t){try{return localStorage.setItem(e,JSON.stringify(t)),!0}catch(e){return console.error("Error writing to localStorage:",e),!1}},remove(e){try{return localStorage.removeItem(e),!0}catch(e){return!1}}},toast={container:null,init(){this.container=document.getElementById("toastContainer")},show(e,t="info",n=3e3){this.container||this.init();const o=document.createElement("div");o.className=`toast ${t}`,o.innerHTML=`\n            <span class="toast-icon">${{success:"✅",error:"❌",warning:"⚠️",info:"ℹ️"}[t]}</span>\n            <span class="toast-message">${e}</span>\n            <button class="toast-close" onclick="this.parentElement.remove()">×</button>\n        `,this.container.appendChild(o),setTimeout(()=>{o.style.animation="toastSlideIn 0.3s ease reverse",setTimeout(()=>o.remove(),300)},n)},success(e){this.show(e,"success")},error(e){this.show(e,"error")},warning(e){this.show(e,"warning")},info(e){this.show(e,"info")}},modal={overlay:null,modalEl:null,init(){this.overlay=document.getElementById("modalOverlay"),this.modalEl=document.getElementById("modal"),document.getElementById("modalClose").addEventListener("click",()=>this.close()),this.overlay.addEventListener("click",e=>{e.target===this.overlay&&this.close()})},open(e,t,n=""){this.overlay||this.init(),document.getElementById("modalTitle").textContent=e,document.getElementById("modalBody").innerHTML=t,document.getElementById("modalFooter").innerHTML=n,this.overlay.classList.add("active"),document.body.style.overflow="hidden"},close(){this.overlay.classList.remove("active"),document.body.style.overflow=""}};function calculateFoodCost(e,t){return 0===t?0:(e/t*100).toFixed(1)}function calculateSuggestedPrice(e,t){return 0===t?0:1e3*Math.ceil(e/(t/100)/1e3)}function getInventoryStatus(e,t){return e<=.5*t?"low":e<=t?"warning":e>2*t?"excess":"ok"}function getStatusBadge(e,t){return`<span class="status-badge ${e}">${t}</span>`}function debounce(e,t){let n;return function(...o){clearTimeout(n),n=setTimeout(()=>{clearTimeout(n),e(...o)},t)}}window.utils={formatCurrency:formatCurrency,formatNumber:formatNumber,formatPrice:formatPrice,getCurrentDate:getCurrentDate,getCurrentTime:getCurrentTime,generateId:generateId,storage:storage,toast:toast,modal:modal,calculateFoodCost:calculateFoodCost,calculateSuggestedPrice:calculateSuggestedPrice,getInventoryStatus:getInventoryStatus,getStatusBadge:getStatusBadge,debounce:debounce};